from lib import *
S = SS('v38')
steps = [
    step("Director / Rewrite 对请求头的处理。client 发 Host: shop.test,带伪造的 X-Forwarded-For: 6.6.6.6、X-Forwarded-Host: evil、Connection: keep-alive, X-Fake、Keep-Alive、Te: trailers。Director 只改 URL:后端看到的 Host 仍是 shop.test;X-Forwarded-For 变成 6.6.6.6, 127.0.0.1(伪造的在最左边);伪造的 X-Forwarded-Host: evil 原样转发。director-host(也把 req.Host 改成后端):Host 是 127.0.0.1:端口,其余同上。Rewrite 加 SetURL(rewrite-nox):Host 是后端的;client 带的 X-Forwarded-* 全部被丢掉,后端一个也看不到。Rewrite 加 SetXForwarded:X-Forwarded-For 是 127.0.0.1(覆盖,伪造的没了),X-Forwarded-Host 是 shop.test,X-Forwarded-Proto 是 http。四种写法都去掉了 Keep-Alive 和 Connection 里点名的 X-Fake,Te: trailers 保留。", t=tl(S(1)), mark=lidx(S(1), 'director      |', 'director-host'), done=lidx(S(1), 'rewrite-nox', 'rewrite       |'), b=bars([['Director:后端看到的 XFF', 1, '6.6.6.6, 127.0.0.1'], ['Director:X-Forwarded-Host', 1, 'evil(伪造的转发)'], ['Rewrite + SetXForwarded:XFF', 1, '127.0.0.1(覆盖)'], ['Rewrite:不调用 SetXForwarded', 0, '全部丢掉']], 1, mark=[0, 1], done=[2, 3]), kv=KV([['Director', '伪造的 XFF 和 X-Forwarded-Host 都保留'], ['Rewrite + SetXForwarded', '用代理看到的 client 信息覆盖'], ['逐跳头', 'Keep-Alive 与 Connection 里点名的头被去掉']], ['Director'])),
    step("错误处理。(a) 后端端口没人监听:默认 ErrorHandler 回 502、响应体为空;自定义 ErrorHandler 回 503 加 JSON {\"error\":\"upstream_unavailable\"}。(b) 后端 1 s 才回响应头、代理设 ResponseHeaderTimeout 300 ms:同样,默认 502,自定义 503。(c) 后端发了响应头和 10 字节响应体就断开(Content-Length 100):两种 ErrorHandler 的结果一样,client 的 HTTP 库抛 RemoteDisconnected,一个字节的响应都没收到,不是 5xx(我的解释是响应头还在代理的写缓冲里没发出去,没有单独验证)。(d) client 一关连接,后端读到 EOF 用了 0.3 s(就是 client 关闭的那一刻),说明取消被传给了后端。", t=tl(S(2)), mark=lidx(S(2), 'custom'), done=lidx(S(2), 'default'), b=bars([['(a) 默认 ErrorHandler', 502, '502(空体)'], ['(a) 自定义 ErrorHandler', 503, '503 + JSON'], ['(c) 响应体断一半', 0, 'RemoteDisconnected(没有响应)']], 503, done=[0], mark=[1], cur=[2]), kv=KV([['默认 ErrorHandler', '连接被拒和超时都是 502,体为空'], ['自定义 ErrorHandler', '503 + JSON'], ['响应体发一半就断', 'client 抛 RemoteDisconnected']], ['响应体发一半就断'])),
    step("Transport 的连接池。http.Transport 的 MaxIdleConnsPerHost 默认是 2。50 个并发线程共发 2000 个请求(后端处理 5 ms),都成功。MaxIdleConnsPerHost = 2:后端 accept 了 725 条连接,复用率 63.7%。MaxIdleConnsPerHost = 100:后端只 accept 了 50 条连接,复用率 97.5%。并发超过空闲连接数时,多出来的连接用完就被关掉,下一批请求又要新建;和 nginx 的 upstream keepalive N 是同一类问题,只是 Go 的默认值更小。", t=tl(S(3)), mark=lidx(S(3), 'MaxIdleConnsPerHost = 2 '), done=lidx(S(3), 'MaxIdleConnsPerHost = 100'), b=bars([['idle = 2:后端连接数', 725, '725'], ['idle = 100:后端连接数', 50, '50'], ['idle = 2:复用率 %', 63.7, '63.7%'], ['idle = 100:复用率 %', 97.5, '97.5%']], 725, mark=[0, 2], done=[1, 3]), kv=KV([['MaxIdleConnsPerHost = 2(默认)', '2000 个请求 725 条连接'], ['MaxIdleConnsPerHost = 100', '50 条连接']], ['MaxIdleConnsPerHost = 2(默认)'])),
    step("流式响应要不要 FlushInterval。后端每 0.3 s 发一个 chunk(chunked,没有 Content-Length),共 5 个。FlushInterval = 0(默认):第 1 个 chunk 0.00 s 就到,第 5 个 1.22 s,共收到 5 个。FlushInterval = -1:0.00 s、1.23 s、5 个。两个配置没有区别。据我对 Go 源码里 flushInterval 函数的记忆,ReverseProxy 对 ContentLength 为 -1(如 chunked)和 text/event-stream 的响应总是立刻 flush,FlushInterval 只对其它响应起作用;这里只验证了 chunked,没有单独测 SSE,也没有读源码核对。", t=tl(S(4)), mark=lidx(S(4), 'FlushInterval = -1'), done=lidx(S(4), 'FlushInterval = 0'), b=bars([['FlushInterval 0:第 1 个 chunk s', 0.0, '0.00'], ['FlushInterval 0:第 5 个 chunk s', 1.22, '1.22'], ['FlushInterval -1:第 5 个 chunk s', 1.23, '1.23']], 1.3, done=[0, 1], mark=[2]), kv=KV([['chunked 响应', '两个配置都是逐块立刻到达'], ['第 5 个 chunk', '1.22 s 与 1.23 s']], ['chunked 响应'])),
]
A = mkartv('v38', 38, '微服务,网关,Go,ReverseProxy,Director,Rewrite,错误处理,真实验证,动画演示',
    '实测 Go 的 httputil.ReverseProxy:Director 写法转发伪造的 X-Forwarded-For 与 X-Forwarded-Host、不改 Host,Rewrite 加 SetXForwarded 才覆盖;默认 ErrorHandler 对连接被拒和超时都回空体 502;MaxIdleConnsPerHost 默认 2 时 2000 个请求用了 725 条后端连接,调到 100 只要 50 条。',
    '用 Go 标准库写一个反向代理要注意什么?Director 和 Rewrite 对请求头的处理有什么不同?各种后端故障 client 会看到什么?Transport 的连接池默认值会怎样?这篇用约 70 行的 Go 代理逐项量出来,并和 nginx 的行为对照。',
    [('伪造的 XFF 保留', 'Director 写法下,client 伪造的 X-Forwarded-For: 6.6.6.6 到后端是 6.6.6.6, 127.0.0.1;Rewrite + SetXForwarded 才被覆盖成 127.0.0.1'), ('502 空体', '默认 ErrorHandler 对后端不可达和响应头超时的响应,换成自定义 ErrorHandler 才能回 503 加 JSON'), ('725 对 50', '2000 个请求、50 个并发时,MaxIdleConnsPerHost 默认 2 与 100 下后端 accept 的连接数')],
    [('请求头', '<p>Director 保留 client 带的 X-Forwarded-*;Rewrite 先丢掉再由 SetXForwarded 重新设置。</p>'),
     ('错误处理', '<p>默认 502 空体;响应体发一半就断时 client 看到连接被直接关闭。</p>'),
     ('连接池', '<p>MaxIdleConnsPerHost 默认只有 2,并发高时连接复用率低。</p>'),
     ('流式', '<p>chunked 响应默认就逐块 flush。</p>')],
    steps,
    [ENV_V + '。代理是 Go 1.27.1 标准库的 net/http/httputil.ReverseProxy(vtmp/v38/main.go,约 70 行,用参数切换写法);后端是 Python 服务或原始 TCP 服务;client 是 Python;(c) 与 (d) 的解释部分已在正文里标明是推测或未单独验证;每个场景只测一次',
     '没有验证:Go 源码里 flushInterval、ErrorHandler 的实现细节(上面的说明凭记忆,已标明);HTTP/2 后端;WebSocket 的升级处理(ReverseProxy 自动处理 101);请求体很大时的 Transport 行为;ModifyResponse;httputil.ReverseProxy 与 context 取消在更多情形下的行为'],
    'Go 手写反向代理')
